SOURCE_4 = "\n// Uploaded sprite sheets are media only. Animation is driven by the 30 Hz game clock.\nexport function drawBackground(g,a,t,scroll=0,phase=1){\n g.save();g.fillStyle='#030b06';g.fillRect(0,0,640,330);\n g.globalAlpha=.3;const offset=((scroll*.09)%240+240)%240;\n for(let row=0;row<2;row++)for(let col=-1;col<4;col++)a.draw('sheet_vines_green',col*240-offset+120,166+row*166,240,166,0);\n g.globalAlpha=.25;const lattice=((scroll*.23)%180+180)%180;\n for(let col=-1;col<5;col++)a.draw('sheet_lattice',col*180-lattice+90,325,180,180,0);\n g.globalAlpha=.17;a.draw('sheet_vines_front',40,330,240,270,0);a.draw('sheet_vines_front',610,330,240,270,0);\n // Rotating flowers and leaves keep their sheet frame order.\n g.globalAlpha=.55;for(let i=0;i<7;i++){const x=((i*111-scroll*.16)%780+780)%780-60;a.draw('sheet_flower',x,35+Math.sin(t*.025+i)*8,28,28,t/4+i*3);a.draw('sheet_leaf',x+35,320+Math.sin(t*.02+i)*5,22,30,t/4+i*4);}\n g.globalAlpha=.65;for(let i=0;i<18;i++){const x=((i*71-t*(.6+i%3*.18)-scroll*.12)%730+730)%730-45,y=45+(i*43+t*(.14+i%2*.07))%265;a.draw('sheet_petals',x,y,14,10,((phase+i)%7)*4+Math.floor(t/6+i)%4);}\n g.restore();\n}\nconst CLIPS=[\n {idle:'spr_krisb_idle',intro:'spr_krisb_intro',hurt:'spr_krisb_hurt',defend:'spr_krisb_defend',pose:'spr_kris_y_pose',spin:'spr_krisb_pirouette',blow:'spr_kris_blow_wind',praise:'spr_krisb_bow',attack:'spr_krisb_attack',cast:'spr_krisb_act',item:'spr_krisb_item',act:'spr_krisb_act',defeat:'spr_krisb_defeat',trial:'spr_kris_lawyer'},\n {idle:'spr_susieb_idle',intro:'spr_susie_flowery_greeting_jacket',hurt:'spr_susieb_hurt',defend:'spr_susieb_defend',pose:'spr_susie_m_pose',spin:'spr_susie_pirouette',blow:'spr_susie_blow_wind',praise:'spr_susie_clap',attack:'spr_susieb_attack',cast:'spr_susieb_spell',item:'spr_susieb_item',act:'spr_susieb_act',defeat:'spr_susieb_defeat',trial:'spr_susie_lawyer',throw:'spr_susie_grab'},\n {idle:'spr_ralseib_idle',intro:'spr_ralsei_begin_battle_serious',hurt:'spr_ralsei_hurt_fixed',defend:'spr_ralseib_defend',pose:'spr_ralsei_c_pose',spin:'spr_ralsei_pirouette',blow:'spr_ralsei_blow_wind',praise:'spr_ralsei_battle_clap',attack:'spr_ralseib_attack',cast:'spr_ralseib_spell',item:'spr_ralseib_item',act:'spr_ralseib_act',defeat:'spr_ralseib_defeat',trial:'spr_ralsei_lawyer'}\n];\nexport class Visuals{\n constructor(){this.party=[null,null,null];this.boss=null;this.fx=[];this.t=0;this.events=[];}\n setParty(i,kind,duration=42,loop=false){this.party[i]={kind,start:this.t,end:this.t+duration,loop};this.events.push({actor:i,kind,tick:this.t});if(this.events.length>100)this.events.shift();}\n setTeam(kind,duration=60,loop=false){for(let i=0;i<3;i++)this.setParty(i,kind,duration,loop);}\n setBoss(name,duration=45,loop=false){this.boss={name,start:this.t,end:this.t+duration,loop};}\n effect(kind,x,y,size=55){const clips={hit:['sheet_hit',4,3],parry:['sheet_slap',4,3],heal:['sheet_heal',4,5],sparkle:['sheet_sparkle',6,3],dust:['sheet_dust',5,3],cut:['sheet_cut',3,4],explosion:['sheet_explosion',8,3]};const [name,frames,rate]=clips[kind]||clips.hit;this.fx.push({name,x,y,size,frames,rate,start:this.t});}\n tick(){this.t++;this.fx=this.fx.filter(f=>this.t-f.start<f.frames*f.rate);}\n pose(i,s,mini){let clip=this.party[i],kind='idle',start=0,loop=true;\n  if(s.party[i].hp<=0){kind='defeat';loop=false;}\n  else if(clip&&clip.end>this.t){kind=clip.kind;start=clip.start;loop=clip.loop;}\n  else if(mini?.type==='blow'){kind='blow';loop=true;}\n  else if(mini?.type==='trial'){kind='trial';loop=true;}\n  else if(mini?.type==='throw'&&i===1){kind='throw';loop=false;}\n  else if(s.defending.has(i)){kind='defend';loop=false;}\n  const name=CLIPS[i][kind]||CLIPS[i].idle;\n  const fps=kind==='idle'?6:kind==='spin'?10:kind==='attack'||kind==='defend'?15:8;\n  return {kind,name,frame:Math.max(0,(this.t-start)*fps/30),loop,age:this.t-start};\n }\n drawParty(g,a,s,mini){for(let i=0;i<3;i++){if(mini?.type==='throw'&&i<2)continue;const p=this.pose(i,s,mini),count=a.info(p.name)?.frames.length||1;const frame=p.loop?Math.floor(p.frame)%count:Math.min(count-1,Math.floor(p.frame));let x=120+i*10,y=100+i*96;\n  // Preserve source origin and a fixed 2x pixel scale across poses.\n  const meta=a.info(p.name),idle=a.info(CLIPS[i].idle);if(!meta||!idle)continue;\n  const signed=n=>n>2147483647?n-4294967296:n;\n  const ox=signed(meta.origin?.[0]||0),oy=signed(meta.origin?.[1]||0);\n  const ix=signed(idle.origin?.[0]||0),iy=signed(idle.origin?.[1]||0);\n  const anchorX=x-idle.w+ix*2,anchorY=y-idle.h*2+iy*2;\n  a.draw(p.name,anchorX+(meta.w/2-ox)*2,anchorY+(meta.h-oy)*2,meta.w*2,meta.h*2,frame);\n }}\n bossSprite(a,base='spr_flowery_idle3'){const b=this.boss;if(b&&b.end>this.t){const n=a.info(b.name)?.frames.length||1;const f=(this.t-b.start)/4;return {name:b.name,frame:b.loop?f:Math.min(n-1,f)};}return {name:base,frame:this.t/6};}\n drawFX(g,a){for(const f of this.fx){const age=this.t-f.start;g.save();g.globalAlpha=Math.min(1,(f.frames*f.rate-age)/5);a.draw(f.name,f.x,f.y+f.size/2,f.size,f.size,Math.floor(age/f.rate));g.restore();}}\n drawHUD(g,a,s){for(let i=0;i<3;i++){a.draw(CLIPS[i].idle,24+i*212,366,24,29,0);const p=this.party[i];if(p?.kind==='hurt'&&p.end>this.t){g.save();g.globalAlpha=.35*Math.max(0,(p.end-this.t)/24);g.fillStyle='#ff6565';g.fillRect(12+i*212,337,197,42);g.restore();}if(s.defending.has(i))a.draw('sheet_sparkle',186+i*212,367,17,17,this.t/4);}}\n}\n\n"

